    image_patch = ImagePatch(image)
    baby_giraffe_patches = image_patch.find("baby giraffe")
    adult_giraffe_patches = image_patch.find("adult giraffe")

    if not baby_giraffe_patches or not adult_giraffe_patches:
        return image_patch

    # Find the baby giraffe next to the adult giraffe
    for baby in baby_giraffe_patches:
        for adult in adult_giraffe_patches:
            if abs(baby.horizontal_center - adult.horizontal_center) < 100 and is_behind(baby, adult):
                return baby

    # If no specific match, return the first baby giraffe found
    return baby_giraffe_patches[0] if baby_giraffe_patches else image_patch

