def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    woman_patches = image_patch.find("woman")
    phone_patches = image_patch.find("phone")

    if not woman_patches or not phone_patches:
        return image_patch

    woman_patches.sort(key=lambda w: w.vertical_center)
    phone_patches.sort(key=lambda p: p.vertical_center)

    closest_woman = woman_patches[0]
    closest_phone = min(phone_patches, key=lambda p: abs(p.vertical_center - closest_woman.vertical_center))

    if closest_phone.vertical_center < closest_woman.vertical_center:
        return closest_woman.crop(closest_phone.left, closest_phone.lower, closest_phone.right, closest_phone.upper)
    else:
        return closest_phone.crop(closest_woman.left, closest_woman.lower, closest_woman.right, closest_woman.upper)

